dtsPropsFor.Btn:
/** Visual treatment. `primary` is the solid orange CTA — one per view; `ghost` is the bordered secondary action beside it. */
variant?: 'primary' | 'ghost';
/** Set this and the component renders an <a> instead of a <button>, with the anchor attributes below available. */
href?: string;
children: React.ReactNode;
/** Appended to `btn btn-<variant>` — safe for layout classes. */
className?: string;
onClick?: React.MouseEventHandler<HTMLElement>;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
target?: string;
rel?: string;

dtsPropsFor.DsLink:
children: React.ReactNode;
/** An internal path renders a Next Link; an http(s) URL renders an anchor with target="_blank" rel="noopener noreferrer"; omitting href gives a click-only <a href="#">. */
href?: string;
onClick?: React.MouseEventHandler<HTMLAnchorElement>;

dtsPropsFor.Section:
/** Anchor target for in-page navigation. */
id?: string;
/** Flip the band to the warm paper surface (--paper / --ink). Cards, buttons and body copy inside switch to their light treatment automatically. */
light?: boolean;
/** 64px of vertical padding instead of 96px, for a band that belongs with the one above it. */
tight?: boolean;
children: React.ReactNode;
/** Escape hatch for a one-off background or offset. */
style?: React.CSSProperties;

dtsPropsFor.Stat:
/** The figure, as a string. Non-numeric values are idiomatic in this design system ("Auto", "Multi", "1 uur", "Headless"), and a Dutch thousands separator ("1.200") stays intact. */
num: string;
/** What the figure measures. One line, sentence case — the stylesheet uppercases it. */
label: string;
/** Unit, rendered smaller and in accent orange: "%", "u", "x". */
suffix?: string;

dtsPropsFor.Numbered:
/** Step number, zero-padded in the house style: "01". */
n: string;
title: string;
/** One or two sentences, rendered inside a <p>. */
children: React.ReactNode;

dtsPropsFor.PillarCard:
/** Short mono label, numbered in the house style: "01 / FOLDERS". */
tag: string;
title: string;
/** One or two sentences in plain language. */
desc: string;
/** Three to five short phrases — concrete deliverables, not benefits. */
items: string[];
/** The whole card is the click target. */
onClick?: () => void;

dtsPropsFor.CaseCard:
/** Sector or client type in mono caps: "FINANCIEEL". */
industry: string;
/** What was achieved — not the client name. */
title: string;
snippet: string;
/** The single number this case is remembered by; pinned to the bottom of the card so metrics align across a row. */
metric: { num: string; label: string };

dtsPropsFor.Pill:
children: React.ReactNode;
/** The green status dot. Defaults to true; set false for a neutral label. */
withDot?: boolean;

dtsPropsFor.LogoBar:
/** Client names as plain strings — this design system sets logos as type, not images. Defaults to ['ABN AMRO', 'NS', 'DIM Haarlem', 'NovaSkin']. Only ever pass real clients. */
logos?: string[];
/** Dimmed mono tail for work that can't be named; production passes the translated "+ en andere". */
more?: string;

dtsPropsFor.LogoMark:
/** Rendered size in px. Default 28. Below 24 use `compact`. */
size?: number;
/** Bracket colour. Defaults to `currentColor`, so the mark inherits the surrounding text colour and works on both the dark and the paper surface without a variant prop. */
bracket?: string;
/** Folder colour — the one place the accent is allowed. Defaults to var(--accent). */
folder?: string;
/** Heavier brackets and a larger folder, for 14-24px. Set automatically by `Logo` below 24. */
compact?: boolean;
className?: string;
style?: React.CSSProperties;
/** Sets role="img" and an accessible name; without it the mark is aria-hidden. */
title?: string;

